"use strict";

const table = Array.from({ length: 21 }, (_, index) => ({
  key: "entry-" + index,
  value: index + 1,
}));

function checksum() {
  return table.reduce((sum, entry) => sum + entry.value, 0);
}

exports.summarize = function summarize(label) {
  const selected = table.filter((entry) => entry.value % 7 === 0).length;
  return [
    "compile-cache:reusable-graph",
    String(label.length),
    String(selected * 7),
    String(checksum() === 231),
  ].join("/");
};
